import app from 'flarum/forum/app';
import DiscussionControls from 'flarum/forum/utils/DiscussionControls';
export const t = (key, params = {}) => app.translator.trans(`ernestdefoe-answers.forum.${key}`, params);
export const STATES = ['unanswered', 'answered', 'solved', 'duplicate'];
export const isQuestion = discussion => !!discussion && !!discussion.attribute('answersQuestion');
export const state = discussion => STATES[discussion.attribute('answersState') || 0] || 'unanswered';

/** Whether any tag this forum shows is a Q&A tag (the nav link only appears then). */
export const qaTags = () => app.store.all('tags').filter(tag => tag.attribute('answersEnabled'));
export const currentQaTag = () => {
  const slug = m.route.param('tags');
  if (!slug) return null;
  const tag = app.store.all('tags').find(tag => tag.slug() === slug);
  return tag && tag.attribute('answersEnabled') ? tag : null;
};
export const postDiscussion = post => post.discussion() || null;

/** A JSON request to our own endpoints; errors show Flarum's alert. */
export function call(method, path, body) {
  return app.request({
    method,
    url: app.forum.attribute('apiUrl') + path,
    body
  });
}
export const formatNumber = n => (n || 0).toLocaleString();

/** Answer: core's reply composer; the thread notices the new post and shows it. */
export function answer(discussion) {
  return DiscussionControls.replyAction.call(discussion, true, false).catch(() => {});
}